<?php
require_once __DIR__.'/../includes/admin_layout.php'; $file=__DIR__.'/../data/users.json'; $users=readJson($file); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $action=$_POST['action']??''; foreach($users as &$u){if((int)($u['id']??0)===$id){if($action==='toggle')$u['status']=($u['status']??'active')==='active'?'blocked':'active'; if($action==='role' && in_array($_POST['role']??'', ['customer','staff','admin'],true))$u['role']=$_POST['role'];}}unset($u);writeJson($file,$users);$msg='User updated.';}
adminStart('Users & Staff','users'); if($msg):?><div class="notice success">✅ <?=h($msg)?></div><?php endif;?><section class="admin-panel"><div class="table-wrap"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($users as $u):?><tr><td><?=h($u['id'])?></td><td><?=h($u['name'])?></td><td><?=h($u['email'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="id" value="<?=h($u['id'])?>"><input type="hidden" name="action" value="role"><select name="role" class="form-control compact" onchange="this.form.submit()"><?php foreach(['customer','staff','admin'] as $r):?><option <?=$u['role']===$r?'selected':''?>><?=$r?></option><?php endforeach;?></select></form></td><td><span class="badge <?=($u['status']??'active')==='active'?'completed':'cancelled'?>"><?=h($u['status']??'active')?></span></td><td><form method="post"><input type="hidden" name="id" value="<?=h($u['id'])?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-secondary"><?=($u['status']??'active')==='active'?'Block':'Activate'?></button></form></td></tr><?php endforeach;?></table></div></section><?php adminEnd();?>